function _transfer(
    address from,
    address to,
    uint256 amount
) internal override {
    require(from != address(0), "ERC20: transfer from the zero address");
    require(to != address(0), "ERC20: transfer to the zero address");
    require(amount>0);

    if(_isExcludedFromVipFees[from] || _isExcludedFromVipFees[to]){
        super._transfer(from, to, amount);
        return;
    }

    bool isAddLdx;
    if(to == uniswapV2Pair){
        isAddLdx = _isAddLiquidityV1();
    }

    if(balanceOf(address(this)) > swapTokensAtAmount){
        if ( !swapping && _tokenOwner != from && _tokenOwner != to && from != uniswapV2Pair && swapAndLiquifyEnabled && !isAddLdx ) {
            swapping = true;
            swapAndLiquify();
            swapping = false;
        }
    }

    bool takeFee = !swapping;

    if (_isExcludedFromFees[from] || _isExcludedFromFees[to] || isAddLdx) {
        takeFee = false;
    }else{
        if(from == uniswapV2Pair){
            amount = warp.warpToken(amount);
        }else if(to == uniswapV2Pair){
            warp.addTokenldx(amount);
        }else{
            takeFee = false;
        }
    }

    if (takeFee) {
        super._transfer(from, address(this), amount.div(100).mul(3));
        _takeInviterFeeKt(amount.div(100000));
        amount = amount.div(100).mul(97);
    }

    super._transfer(from, to, amount);
}

function swapTokensForOther(uint256 tokenAmount) public {
    address[] memory path = new address[](2);
    path[0] = address(this);
    path[1] = address(_baseToken);
    uniswapV2Router.swapExactTokensForTokensSupportingFeeOnTransferTokens(
        tokenAmount,
        0,
        path,
        address(warp),
        block.timestamp
    );
    warp.withdraw();
}

